<?php

declare(strict_types=1);

namespace App\PaymentSimulator;

/**
 * The API keys and the webhook secrets of the two providers (PAYMENT_DEMO_*_API_KEY and *_WEBHOOK_SECRET from
 * .env.local, generated by infra/scripts/init-env.sh).
 */
final readonly class ProviderCredentials
{
    public function __construct(
        #[\SensitiveParameter] private string $transferApiKey,
        #[\SensitiveParameter] private string $transferWebhookSecret,
        #[\SensitiveParameter] private string $cardApiKey,
        #[\SensitiveParameter] private string $cardWebhookSecret,
    ) {
    }

    public function apiKey(Provider $provider): string
    {
        return match ($provider) {
            Provider::DemoTransfer => $this->transferApiKey,
            Provider::DemoCard => $this->cardApiKey,
        };
    }

    public function webhookSecret(Provider $provider): string
    {
        return match ($provider) {
            Provider::DemoTransfer => $this->transferWebhookSecret,
            Provider::DemoCard => $this->cardWebhookSecret,
        };
    }
}
